<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const data=ref(null),candidates=ref(null),goals=ref([]),goalId=ref(null),error=ref(''),writes=useWorkflowWrite('growth-policies')
async function load(){try{const result=await Promise.all([api.flow('/mainlines'),api.flow('/dynamic-candidates'),api.listGoals()]);[data.value,candidates.value,goals.value]=result}catch(e){error.value=e.message}}
async function act(path,body,method='POST'){try{await writes.send(path,body,method);await load();error.value=''}catch(e){error.value=e.message}}
onMounted(async()=>{await act('/discoveries/refresh',{});await load()})
</script>
<template><div><p v-if="error" class="error">{{ error }}</p><section class="card"><h2>当前主线由你选择</h2><p class="muted">只影响已核对事实的金币倾斜，不放大属性。实际投入和档位由分析建议，确认前不入账。</p><label>本人进行中的目标<select v-model="goalId"><option :value="null">选择目标</option><option v-for="goal in goals.filter(g=>g.status==='active')" :key="goal.id" :value="goal.id">{{ goal.description }}</option></select></label><button class="btn" :disabled="writes.busy.value||!goalId" @click="act('/mainlines',{goal_id:goalId,active:true})">选择为当前主线</button><article v-for="row in data?.items" :key="row.id"><p>{{ goals.find(g=>g.id===row.goal_id)?.description||'历史目标' }} · {{ row.active?'当前主线':'历史关联' }}</p><button v-if="row.active" class="btn" :disabled="writes.busy.value" @click="act('/mainlines/'+row.id,{goal_id:row.goal_id,active:false,expected_version:row.version},'PUT')">暂不设主线</button></article></section><section class="card"><h2>发现与核实的成就</h2><p class="muted">按事件与日记的首次保存日分别核实。候选不自动发币，忽略后保留状态；额度满可稍后再领。</p><button class="btn" :disabled="writes.busy.value" @click="act('/discoveries/refresh',{})">检查新的记录里程碑</button><article v-for="row in candidates?.items" :key="row.id"><h3>{{ row.name }}</h3><p>{{ {candidate:'待核对',claimed:'已领取',ignored:'已忽略'}[row.state] }} · 已核实 {{ row.evidence.count }}/{{ row.evidence.target }} 天</p><p>{{ row.trial_terms?'试用奖励 '+row.trial_terms.amount+' 币':'尚无已批准的奖励映射，只保留候选' }}</p><div v-if="row.state==='candidate'" class="action-group"><button class="btn" :disabled="writes.busy.value" @click="act('/dynamic-candidates/'+row.id+'/decision',{expected_version:row.version,action:'verify'})">重新核实</button><button class="btn" :disabled="writes.busy.value" @click="act('/dynamic-candidates/'+row.id+'/decision',{expected_version:row.version,action:'ignore'})">忽略候选</button><button class="btn" :disabled="writes.busy.value||!row.trial_terms||!row.evidence.eligible" @click="act('/dynamic-candidates/'+row.id+'/decision',{expected_version:row.version,action:'claim'})">确认领取</button></div></article></section></div></template>
